const cta=(label='Meet Vortex',style='')=>`<span class="cta ${style}">${label}<span>↗</span></span>`;
const foot=(left='AI Company brain',right='Context, connected.')=>`<div class="mini-footer"><span>${left}</span><span>${right}</span></div>`;
const sketches=[
 {name:'Quiet center',note:'Symmetry. Small mark, large promise, one focal point.',cls:'quiet-center',body:`${nav()}<div class="center-stack">${mark}<span class="micro-label">YOUR COMPANY, CONNECTED</span><h3>One company.<br>One shared mind.</h3><p>Everything your team knows.<br>Ready when you need it.</p>${cta()}</div>${foot('Vortex / 01','Clarity starts here.')}`},
 {name:'The golden split',note:'A 61.8 / 38.2 split with a bold lavender field.',cls:'golden-split',body:`<div class="split-field">${mark}<span>KNOWLEDGE<br>IN MOTION.</span></div>${nav('')}<div class="split-copy"><span class="micro-label">AI COMPANY BRAIN</span><h3>Bring it<br>all together.</h3><p>Your knowledge. Your decisions.<br>One place to connect the dots.</p>${cta('Find your context')}</div>${foot('Vortex','01 — A shared intelligence')}`},
 {name:'Type as the hero',note:'Oversized language leads. The symbol acts as punctuation.',cls:'type-hero',body:`${nav('THE AI COMPANY BRAIN')}<div class="type-title"><h3>EVERYTHING.<br>CONNECTED<span class="type-dot">.</span></h3></div><div class="type-lower">${mark}<p>The context behind<br>every good decision.</p>${cta('Enter Vortex','outline')}</div>${foot('Less searching. More knowing.','V / 003')}`},
 {name:'Ask first',note:'A search-led product introduction with very little framing.',cls:'ask-first',body:`${nav('A SHARED INTELLIGENCE')}<div class="ask-center">${mark}<h3>What does your<br>company know?</h3><div class="search-mock"><span>Ask your company anything…</span><span class="send-arrow">↗</span></div><div class="suggestions"><span>Find a decision</span><span>Understand a project</span><span>Connect the dots</span></div></div>${foot('AI Company brain','Knowledge, in context.')}`},
 {name:'The purple poster',note:'A full purple field, a monumental mark, a short statement.',cls:'purple-poster',body:`${nav('V / 005')}<h3>A company.<br>A shared mind.</h3><i class="mark poster-mark" aria-hidden="true"></i><div class="poster-bottom"><p>AI Company brain</p>${cta('Meet Vortex','outline')}</div>`},
 {name:'A light touch',note:'A pale canvas and a single floating card. Calm and approachable.',cls:'light-touch',body:`${nav('AI Company brain')}<div class="light-copy"><span class="micro-label">LESS NOISE. MORE CONTEXT.</span><h3>Make knowing<br>second nature.</h3><p>Bring your company’s knowledge<br>into the conversation.</p>${cta('Discover Vortex')}</div><div class="answer-card">${brand}<span class="card-rule"></span><span class="micro-label">A QUESTION WORTH ASKING</span><h4>Why did we<br>choose this direction?</h4><p>Start with the decision.<br>Follow the thinking behind it.</p><div class="source-pills"><span>Decisions</span><span>Notes</span><span>Context</span></div></div>${foot('Your company, in context.','VORTEX')}`}
 ,{name:'The side rail',note:'A vertical identity strip and a crisp, left-aligned introduction.',cls:'side-rail',body:`<div class="identity-rail">${mark}<span>VORTEX / AI COMPANY BRAIN</span><span class="rail-issue">007</span></div><div class="rail-nav"><span>A shared intelligence.</span><span>Meet Vortex ↗</span></div><div class="rail-copy"><span class="micro-label">YOUR KNOWLEDGE, IN REACH</span><h3>Context is<br>everything.</h3><div class="rail-bottom"><p>Keep the thinking.<br>Connect the knowledge.<br>Move forward, together.</p>${cta('Find your clarity')}</div></div><div class="rail-baseline"><span>Vortex</span><span>KNOW → CONNECT → ACT</span></div>`}
 ,{name:'The product canvas',note:'A compact headline above a wide, layered glimpse of the product.',cls:'product-canvas',body:`${nav('AI Company brain')}<div class="canvas-heading"><h3>All the context.<br>None of the switching.</h3>${cta('Meet your company brain')}</div><div class="product-window"><div class="window-bar">${brand}<span>COMPANY KNOWLEDGE</span><span>⌘ K</span></div><div class="window-body"><div class="window-sidebar"><b>Workspace</b><span>Overview</span><span class="active">Company brain</span><span>Decisions</span><span>Sources</span></div><div class="window-main"><span class="micro-label">A SHARED UNDERSTANDING</span><h4>What are we thinking about?</h4><div class="window-search">Ask a question about your company <span>↵</span></div><div class="context-tiles"><div><span>01 / DECISIONS</span><b>Follow the why.</b></div><div><span>02 / KNOWLEDGE</span><b>See the whole picture.</b></div></div></div></div></div><span class="canvas-foot">KNOWLEDGE / DECISIONS / CONTEXT</span>`}
 ,{name:'Wordmark horizon',note:'Instrument Sans for the wordmark and copy. JetBrains Mono for the labels.',cls:'wordmark-horizon',body:`<div class="horizon-top"><span class="micro-label">AI COMPANY BRAIN</span><span>MEET VORTEX ↗</span></div><div class="horizon-copy"><h3>Good thinking<br>belongs together.</h3><p>One shared brain for everything<br>your company knows.</p></div><i class="mark horizon-mark" aria-hidden="true"></i><div class="horizon-word">Vortex</div><span class="horizon-label">A SHARED INTELLIGENCE.</span>`}
 ,{name:'Orbit',note:'The mark becomes the focal point inside a quiet system of rings.',cls:'orbit',body:`${nav('INTELLIGENCE, IN CONTEXT')}<div class="orbital-system"><span class="orbit-ring r1"></span><span class="orbit-ring r2"></span><span class="orbit-ring r3"></span>${mark}<span class="orbit-point p1"></span><span class="orbit-point p2"></span></div><div class="orbit-copy"><span class="micro-label">CONNECTED BY DESIGN</span><h3>Bring your<br>world together.</h3><p>One place for your company’s<br>knowledge to become understanding.</p>${cta('Enter Vortex','outline')}</div>${foot('AI Company brain','V / 010')}`}
 ,{name:'The editorial',note:'A more human direction: expressive type, a ruled page, a small mark.',cls:'editorial',body:`<div class="editorial-masthead"><span>VORTEX</span><span>THE COMPANY INTELLIGENCE EDITION</span><span>NO. 011</span></div><div class="editorial-title"><span class="micro-label">A NEW WAY TO KNOW.</span><h3>Knowledge<br>is a <em>shared</em><br>advantage.</h3></div><div class="editorial-aside">${mark}<span class="editorial-rule"></span><p>The decisions, ideas, and context<br>that move your company.<br>Connected.</p>${cta('Meet Vortex','outline')}</div><div class="editorial-bottom"><span>AI Company brain</span><span>Less searching. More understanding.</span></div>`}
 ,{name:'Pure identity',note:'The smallest possible statement. Symbol, name, descriptor.',cls:'pure-identity',body:`<div class="pure-top"><span>V / 012</span><span>A SHARED INTELLIGENCE</span></div><div class="pure-lockup">${mark}<h3>Vortex</h3></div><p class="pure-descriptor">AI Company brain</p><div class="pure-bottom"><span>Everything you know. Connected.</span><span>Discover Vortex <b>↗</b></span></div>`}
];
const grid='<div class="phi-overlay" aria-hidden="true"><i class="v a"></i><i class="v b"></i><i class="h a"></i><i class="h b"></i></div>';
const $=s=>document.querySelector(s);
function stage(s){return `<div class="sketch-stage ${s.cls}">${s.body}${grid}</div>`;}
function render(){ $('#sketch-grid').innerHTML=sketches.map((s,i)=>`<article class="sketch-card"><div class="thumbnail"><div aria-hidden="true">${stage(s)}</div><button class="open-sketch" data-index="${i}" aria-label="Enlarge ${String(i+1).padStart(2,'0')} — ${s.name}"><span>↗</span></button></div><div class="sketch-caption"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h2>${s.name}</h2><p>${s.note}</p></div></div></article>`).join(''); }
let current=0,opener;
function show(index){current=(index+sketches.length)%sketches.length;const s=sketches[current];$('#viewer-title').textContent=s.name;$('#viewer-count').textContent=`LANDING STUDY / ${String(current+1).padStart(2,'0')}`;$('#viewer-position').textContent=`${current+1} / ${sketches.length}`;$('#viewer-note').textContent=s.note;$('#viewer-art').innerHTML=stage(s);}
$('#sketch-grid').addEventListener('click',e=>{const button=e.target.closest('[data-index]');if(!button)return;opener=button;show(+button.dataset.index);$('#viewer').showModal();document.body.classList.add('viewing');});
$('#close-viewer').addEventListener('click',()=>$('#viewer').close());
$('#viewer').addEventListener('close',()=>{document.body.classList.remove('viewing');opener?.focus({preventScroll:true});});
$('#viewer').addEventListener('click',e=>{if(e.target===$('#viewer')){const r=$('#viewer').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#viewer').close();}});
$('#previous').addEventListener('click',()=>show(current-1));$('#next').addEventListener('click',()=>show(current+1));
$('#viewer').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();show(current+1);}if(e.key==='ArrowLeft'){e.preventDefault();show(current-1);}});
$('#grid-toggle').addEventListener('click',()=>{const on=$('#grid-toggle').getAttribute('aria-pressed')!=='true';$('#grid-toggle').setAttribute('aria-pressed',String(on));$('#grid-toggle span').textContent=on?'Hide grids':'Show grids';document.body.classList.toggle('show-grids',on);});
render();
